// Abstract Employee Manager and Programmer
public class Q10 {abstract static class Employee {String name;Employee(String n){name=n;}abstract double calculateSalary();abstract void displayInfo();}static class Manager extends Employee {double base,bonus;Manager(String n,double b,double x){super(n);base=b;bonus=x;}double calculateSalary(){return base+bonus;}void displayInfo(){System.out.println("Manager "+name+" salary "+calculateSalary());}}static class Programmer extends Employee {double base,allowance;Programmer(String n,double b,double x){super(n);base=b;allowance=x;}double calculateSalary(){return base+allowance;}void displayInfo(){System.out.println("Programmer "+name+" salary "+calculateSalary());}}public static void main(String[] args){new Manager("Asha",50000,10000).displayInfo();new Programmer("Ravi",40000,8000).displayInfo();}}
